CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz DEFAULT now(),"updatedAt" timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,role text NOT NULL DEFAULT 'member' CHECK(role IN ('admin','member')));
CREATE TABLE IF NOT EXISTS records (id uuid NOT NULL,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('source','highlight','theme','card')),data jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS records_kind ON records(user_id,kind);
CREATE INDEX IF NOT EXISTS records_search ON records USING gin(to_tsvector('simple',data::text));
CREATE TABLE IF NOT EXISTS settings (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS review_days (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,date date NOT NULL,highlight_ids uuid[] NOT NULL,actions jsonb NOT NULL DEFAULT '{}',completed boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,date));
CREATE TABLE IF NOT EXISTS changes (seq bigserial PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,entity text NOT NULL,id uuid NOT NULL,deleted boolean NOT NULL DEFAULT false,data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS changes_owner_cursor ON changes(user_id,seq);
CREATE TABLE IF NOT EXISTS sync_ops (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,op_id uuid NOT NULL,result jsonb NOT NULL,PRIMARY KEY(user_id,op_id));
CREATE TABLE IF NOT EXISTS import_previews (id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,data jsonb NOT NULL,committed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integrations (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,provider text NOT NULL,secret text NOT NULL,config jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'configured',last_error text,PRIMARY KEY(user_id,provider));
CREATE TABLE IF NOT EXISTS deliveries (id uuid PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,highlight_id uuid NOT NULL,provider text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','ambiguous','failed')),remote_id text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,highlight_id,provider));
CREATE TABLE IF NOT EXISTS invites (id uuid PRIMARY KEY,email text NOT NULL,token_hash text NOT NULL UNIQUE,created_by text NOT NULL REFERENCES "user"(id),expires_at timestamptz NOT NULL,used_at timestamptz);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['records','settings','review_days','changes','sync_ops','import_previews','integrations','deliveries'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);IF NOT EXISTS(SELECT FROM pg_policies WHERE tablename=t AND policyname='owner_access') THEN EXECUTE format('CREATE POLICY owner_access ON %I USING (user_id=current_setting(''app.user_id'',true)) WITH CHECK (user_id=current_setting(''app.user_id'',true))',t);END IF;END LOOP;END $$;
